// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // Seed the market to make initialized true
        vm.deal(address(this), 1 ether);
        c.seedMarket{value: 1 ether}(100);
        // Now call DrugDealer from any address (it only works from ceoAddress, but we just test after)
        vm.prank(caller);
        // We don't need a successful call; just execute it
        (bool success, ) = address(c).call(abi.encodeWithSignature("DrugDealer()"));
        // Rule: initialized must be true after any call to DrugDealer
        assertTrue(c.initialized());
    }
}

